  ''
).trim();

if (!whatsappTo) {
  throw new Error('No existe destino WhatsApp. Falta reply_to_jid, remote_jid, from_jid o phone.');
}

return [
  {
    json: {
      ...$json,
      whatsapp_to: whatsappTo,
      whatsapp_message: $json.reply
    }
  }
];

