parameters.jsCode:
const input = $json;

const rawPhone = String(input.phone || '').trim();
const replyToJid = String(
  input.reply_to_jid ||
  input.remote_jid ||
  input.from_jid ||
  ''
).trim();

let phone = '';

// phone solo debe ser número real, nunca @lid
if (rawPhone && !rawPhone.includes('@')) {
  phone = rawPhone.replace(/\D/g, '');
}

// Si no vino phone, intentar extraerlo solo de un JID normal
if (!phone && replyToJid.endsWith('@s.whatsapp.net')) {
  phone = replyToJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
}

// Normalización Ecuador
if (phone.startsWith('0')) {
  phone = `593${phone.slice(1)}`;
}

if (!phone.startsWith('593') && phone.length === 9) {
  phone = `593${phone}`;
}

const contactKey =
  input.contact_key ||
  phone ||
  replyToJid ||
  input.from ||
  '';

const messageBody = String(input.body || input.message || '').trim();

let messageType =
  input.message_type ||
  input.type ||
  (messageBody ? 'text' : 'unknown');

messageType = String(messageType)
  .replace(/^=/, '')
  .replace(/^"+|"+$/g, '')
  .trim();

if (!messageType) {
  messageType = messageBody ? 'text' : 'unknown';
}

const messageId = input.message_id || input.id || '';

const idempotencyKey = messageId
  ? `whatsapp:inbound:${contactKey}:${messageId}`
  : `whatsapp:inbound:${contactKey}:${Buffer.from(`${messageBody}:${input.timestamp || ''}`).toString('base64')}`;

return [
  {
    json: {
      ...input,

      phone,
      contact_key: contactKey,

      reply_to_jid: replyToJid || contactKey,
      remote_jid: input.remote_jid || replyToJid || contactKey,
      from_jid: input.from_jid || replyToJid || contactKey,

      message: messageBody,
      message_type: messageType,
      message_id: messageId,
      idempotency_key: idempotencyKey,
      is_empty: !messageBody,
      is_media: Boolean(input.has_media) || !['text', 'unknown'].includes(messageType),
      received_at: new Date((Number(input.timestamp) || Math.floor(Date.now() / 1000)) * 1000).toISOString()
    }
  }
];

