const content = $json.choices?.[0]?.message?.content;

let parsed;

try {
  parsed = content ? JSON.parse(content) : {};
} catch (error) {
  parsed = {};
}

const normalized = $('Normalize + Idempotency').item.json;

return [
  {
    json: {
      phone: normalized.phone,
      contact_key: normalized.contact_key,
      reply_to_jid: normalized.reply_to_jid,
      remote_jid: normalized.remote_jid,
      from_jid: normalized.from_jid,

      original_message: normalized.message,
      channel: normalized.channel || 'whatsapp',
      idempotency_key: normalized.idempotency_key,

      category: parsed.category || 'unknown',
      intent: parsed.intent || 'unknown',
      summary: parsed.summary || 'No se pudo interpretar la respuesta de DeepSeek.',
      confidence: parsed.confidence || 0,
      requires_human: parsed.requires_human ?? true,
      suggested_template: parsed.suggested_template || 'human_handoff',
      lead_priority: parsed.lead_priority || 'medium'
    }
  }
];
